// Generated by Google Stitch, 3 August 2026. Source folder: a-booking_details
//
// WIRED 17 August 2026, task #116, Phase C.
//
// The hub of the manage-a-booking flow. 14 opens it; it opens 27 (change) and
// 28 (cancel), and 15 once the stay is under way.
//
// ── WHAT THIS REPLACED ───────────────────────────────────────────────────
//
// A fixed booking with a fixed price, a "PAID" badge, and Change / Cancel
// buttons with empty handlers. The back arrow was `onPressed: () {}`, so the
// screen could not even be left. A fake bottom navigation bar sat underneath.
//
// ── WHAT IS SHOWN AND WHAT IS HIDDEN ─────────────────────────────────────
//
// Change and Cancel appear only when the booking is genuinely changeable —
// BookingStatus.guestCanCancel, which is pending or confirmed. A cancelled
// stay showing a Cancel button is how a guest ends up tapping something that
// throws, and a completed one showing Change is worse: it suggests a past
// stay can be moved.
//
// The payment card reports what the booking actually records, including
// "no payment taken", rather than a PAID badge that was true of nobody.
import 'package:flutter/material.dart';
import 'package:google_fonts/google_fonts.dart';

import '../models/stay_booking.dart';
import '../models/stay_enums.dart';
import '../models/stay_listing.dart';
import '../services/stay_booking_service.dart';
import '../services/stay_listing_service.dart';
import '../stay_routes.dart';
import '../theme/stay_colors.dart';

class BookingDetailsScreen extends StatefulWidget {
  const BookingDetailsScreen({super.key, required this.bookingId});

  final String bookingId;

  @override
  State<BookingDetailsScreen> createState() => _BookingDetailsScreenState();
}

class _BookingDetailsScreenState extends State<BookingDetailsScreen> {
  StayListing? _listing;
  String? _loadedFor;

  void _ensureListing(String listingId) {
    if (listingId.isEmpty || _loadedFor == listingId) return;
    _loadedFor = listingId;
    _fetch(listingId);
  }

  Future<void> _fetch(String listingId) async {
    try {
      final StayListing? l = await StayListingService.instance.byId(listingId);
      if (!mounted) return;
      setState(() => _listing = l);
    } catch (_) {
      // Everything that matters — dates, price, status, reference — is on the
      // booking. The listing only supplies the title and photo.
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: GoOutsColors.surface,
      appBar: AppBar(
        backgroundColor: Colors.white,
        elevation: 0,
        centerTitle: false,
        leading: IconButton(
          icon: const Icon(Icons.arrow_back, color: GoOutsColors.primaryBlue),
          // Was `onPressed: () {}`. The screen could not be left.
          onPressed: () => Navigator.of(context).pop(),
        ),
        title: Text(
          'Booking details',
          style: GoogleFonts.inter(
            fontSize: 20,
            fontWeight: FontWeight.bold,
            color: GoOutsColors.primaryBlue,
          ),
        ),
        bottom: PreferredSize(
          preferredSize: const Size.fromHeight(1),
          child: Container(color: GoOutsColors.dividerGray, height: 1),
        ),
      ),
      // Watched, not fetched once: a host accepting, or a cancellation
      // completing on the next screen, changes this page underneath the guest.
      body: StreamBuilder<StayBooking?>(
        stream: StayBookingService.instance.watch(widget.bookingId),
        builder: (context, snapshot) {
          if (snapshot.connectionState == ConnectionState.waiting) {
            return const Center(child: CircularProgressIndicator());
          }
          final StayBooking? b = snapshot.data;
          if (b == null) {
            return Center(
              child: Padding(
                padding: const EdgeInsets.all(32),
                child: Text(
                  'This booking could not be found.',
                  textAlign: TextAlign.center,
                  style: GoogleFonts.inter(
                      fontSize: 15, color: GoOutsColors.bodyText),
                ),
              ),
            );
          }

          _ensureListing(b.listingId);

          return SingleChildScrollView(
            child: Column(
              children: [
                const SizedBox(height: 16),
                _listingHeader(b),
                const SizedBox(height: 16),
                _quickInfo(b),
                const SizedBox(height: 16),
                _paymentStatusCard(b),
                const SizedBox(height: 16),
                _actionButtons(b),
                const SizedBox(height: 24),
                _stayManagement(b),
                const SizedBox(height: 16),
                _paymentSummary(b),
                const SizedBox(height: 32),
              ],
            ),
          );
        },
      ),
    );
  }

  // ── Header ───────────────────────────────────────────────────────────────

  Widget _card({required Widget child, EdgeInsets? padding}) => Container(
        margin: const EdgeInsets.symmetric(horizontal: 16),
        padding: padding ?? const EdgeInsets.all(16),
        decoration: BoxDecoration(
          color: Colors.white,
          borderRadius: BorderRadius.circular(12),
          boxShadow: [
            BoxShadow(
              color: Colors.black.withValues(alpha: 0.04),
              blurRadius: 8,
              offset: const Offset(0, 2),
            ),
          ],
        ),
        child: child,
      );

  Widget _listingHeader(StayBooking b) {
    final List<StayPhoto> photos =
        List<StayPhoto>.from(_listing?.photos ?? const <StayPhoto>[])
          ..sort((a, b2) => a.order.compareTo(b2.order));

    return _card(
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          ClipRRect(
            borderRadius: BorderRadius.circular(10),
            child: photos.isEmpty
                ? Container(
                    width: 84,
                    height: 84,
                    color: GoOutsColors.paleBlueTint,
                    child: const Icon(Icons.home_outlined,
                        color: GoOutsColors.primaryBlue),
                  )
                : Image.network(
                    photos.first.url,
                    width: 84,
                    height: 84,
                    fit: BoxFit.cover,
                    errorBuilder: (_, __, ___) => Container(
                      width: 84,
                      height: 84,
                      color: GoOutsColors.paleBlueTint,
                      child: const Icon(Icons.home_outlined,
                          color: GoOutsColors.primaryBlue),
                    ),
                  ),
          ),
          const SizedBox(width: 12),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  _listing?.title ?? 'Your stay',
                  style: GoogleFonts.inter(
                    fontSize: 17,
                    fontWeight: FontWeight.bold,
                    color: GoOutsColors.deepNavy,
                  ),
                ),
                if ((_listing?.address.town ?? '').isNotEmpty)
                  Text(
                    _listing!.address.town,
                    style: GoogleFonts.inter(
                        fontSize: 14, color: GoOutsColors.bodyText),
                  ),
                const SizedBox(height: 8),
                _statusPill(b.status),
              ],
            ),
          ),
        ],
      ),
    );
  }

  Widget _statusPill(BookingStatus s) {
    final chip = _statusChip(s);
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 5),
      decoration: BoxDecoration(
        color: chip.colour.withValues(alpha: 0.1),
        borderRadius: BorderRadius.circular(8),
      ),
      child: Text(
        chip.label,
        style: GoogleFonts.inter(
          fontSize: 11.5,
          fontWeight: FontWeight.w800,
          color: chip.colour,
          letterSpacing: 0.4,
        ),
      ),
    );
  }

  ({String label, Color colour}) _statusChip(BookingStatus s) {
    switch (s) {
      case BookingStatus.pending:
        return (label: 'AWAITING HOST', colour: GoOutsColors.pendingOrange);
      case BookingStatus.confirmed:
        return (label: 'CONFIRMED', colour: GoOutsColors.successGreen);
      case BookingStatus.inProgress:
        return (label: 'YOU ARE THERE', colour: GoOutsColors.primaryBlue);
      case BookingStatus.completed:
        return (label: 'COMPLETED', colour: GoOutsColors.bodyText);
      case BookingStatus.declined:
        return (label: 'DECLINED', colour: GoOutsColors.error);
      case BookingStatus.cancelledGuest:
        return (label: 'YOU CANCELLED', colour: GoOutsColors.error);
      case BookingStatus.cancelledHost:
        return (label: 'HOST CANCELLED', colour: GoOutsColors.error);
      case BookingStatus.disputed:
        return (label: 'UNDER REVIEW', colour: GoOutsColors.warning);
    }
  }

  // ── Quick info ───────────────────────────────────────────────────────────

  static const List<String> _months = <String>[
    'Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
    'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec',
  ];
  static String _d(DateTime d) => '${d.day} ${_months[d.month - 1]}';

  Widget _quickInfo(StayBooking b) {
    final g = b.guests;
    // The three columns are narrow, so this shows the counted headcount only.
    // A full "2 adults, 1 child, 1 infant" breakdown was built here and then
    // not used — it belongs on a wider row, not in a 33% column.
    return _card(
      child: Row(
        children: [
          Expanded(
              child: _info(Icons.login, 'Check in', _d(b.checkIn))),
          Expanded(
              child: _info(Icons.logout, 'Check out', _d(b.checkOut))),
          Expanded(
            child: _info(Icons.people_outline, 'Guests',
                '${g.adults + g.children}'),
          ),
        ],
      ),
    );
  }

  Widget _info(IconData icon, String label, String value) => Column(
        children: [
          Icon(icon, size: 20, color: GoOutsColors.primaryBlue),
          const SizedBox(height: 6),
          Text(label,
              style: GoogleFonts.inter(
                  fontSize: 12, color: GoOutsColors.bodyText)),
          const SizedBox(height: 2),
          Text(value,
              style: GoogleFonts.inter(
                  fontSize: 15,
                  fontWeight: FontWeight.w700,
                  color: GoOutsColors.deepNavy)),
        ],
      );

  // ── Payment ──────────────────────────────────────────────────────────────
  //
  // Reads paymentStatus, which is one of: not_taken, demo_paid, or whatever a
  // real integration writes later. The Stitch version showed a green PAID
  // badge unconditionally, which was true of no booking that has ever existed.

  Widget _paymentStatusCard(StayBooking b) {
    final String status = b.paymentStatus;
    final bool demo = status == 'demo_paid';
    final bool none = status == 'not_taken';

    final IconData icon = none
        ? Icons.schedule
        : demo
            ? Icons.science_outlined
            : Icons.check_circle;
    final Color colour = none
        ? GoOutsColors.pendingOrange
        : demo
            ? GoOutsColors.primaryBlue
            : GoOutsColors.successGreen;
    final String title = none
        ? 'No payment taken'
        : demo
            ? 'Settled in test mode'
            : 'Paid';
    // Built as statements. The nested-ternary-inside-${} version compiled but
    // was unreadable, and unreadable is how the wrong branch survives review.
    final String recorded =
        b.paidPence.isZero ? '' : 'Recorded as ${b.paidPence.formatted}. ';

    final String body;
    if (none) {
      body = 'Your dates are held. If the stay is not paid for within '
          '48 hours the hold is released.';
    } else if (demo) {
      // The split, named. A guest who spent £31 of cashback should see that
      // it went, because it really did leave their wallet.
      final String wallet = b.paidFromWallet.isZero
          ? ''
          : '${b.paidFromWallet.formatted} came off your GoOuts wallet. ';
      body = '${wallet}This booking was settled while GoOuts is in test '
          'mode. ${recorded}No card was charged.';
    } else {
      body = '${b.paidPence.formatted} paid.';
    }

    return _card(
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Icon(icon, color: colour),
          const SizedBox(width: 12),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(title,
                    style: GoogleFonts.inter(
                        fontSize: 15,
                        fontWeight: FontWeight.w700,
                        color: GoOutsColors.deepNavy)),
                const SizedBox(height: 4),
                Text(body,
                    style: GoogleFonts.inter(
                        fontSize: 13.5,
                        height: 1.35,
                        color: GoOutsColors.bodyText)),
              ],
            ),
          ),
        ],
      ),
    );
  }

  // ── Actions ──────────────────────────────────────────────────────────────

  Widget _actionButtons(StayBooking b) {
    // guestCanCancel is pending or confirmed. Anything else — completed,
    // declined, cancelled, in progress, disputed — gets no buttons at all
    // rather than buttons that throw when tapped.
    if (!b.status.guestCanCancel) {
      return const SizedBox.shrink();
    }

    return Padding(
      padding: const EdgeInsets.symmetric(horizontal: 16),
      child: Column(
        children: [
          // ── MESSAGE THE HOST ────────────────────────────────────────────
          //
          // Shown on the same statuses as Change and Cancel — pending and
          // confirmed. A guest with a question before arrival previously had
          // no way to ask one; the only contact route in the app was GoOuts
          // support, who cannot tell them where the key is.
          //
          // Deliberately the FIRST button. Asking a question is far more
          // common than cancelling, and Cancel should not be the most
          // prominent thing a guest sees on their own booking.
          SizedBox(
            width: double.infinity,
            child: FilledButton.icon(
              onPressed: () => Navigator.of(context).pushNamed(
                StayRoutes.messageHost,
                arguments: <String, dynamic>{'bookingId': b.id},
              ),
              icon: const Icon(Icons.chat_bubble_outline_rounded, size: 18),
              label: const Text('Message your host'),
              style: FilledButton.styleFrom(
                minimumSize: const Size(0, 48),
                backgroundColor: GoOutsColors.primaryBlue,
                foregroundColor: Colors.white,
              ),
            ),
          ),
          const SizedBox(height: 12),
          Row(
        children: [
          Expanded(
            child: OutlinedButton.icon(
              onPressed: () => Navigator.of(context).pushNamed(
                StayRoutes.editBooking,
                arguments: <String, dynamic>{'bookingId': b.id},
              ),
              icon: const Icon(Icons.edit_calendar_outlined, size: 18),
              label: const Text('Change'),
              style: OutlinedButton.styleFrom(
                minimumSize: const Size(0, 48),
                foregroundColor: GoOutsColors.primaryBlue,
                side: const BorderSide(color: GoOutsColors.primaryBlue),
              ),
            ),
          ),
          const SizedBox(width: 12),
          Expanded(
            child: OutlinedButton.icon(
              onPressed: () => Navigator.of(context).pushNamed(
                StayRoutes.cancelBooking,
                arguments: <String, dynamic>{'bookingId': b.id},
              ),
              icon: const Icon(Icons.close_rounded, size: 18),
              label: const Text('Cancel'),
              style: OutlinedButton.styleFrom(
                minimumSize: const Size(0, 48),
                foregroundColor: GoOutsColors.error,
                side: const BorderSide(color: GoOutsColors.error),
              ),
            ),
          ),
        ],
          ),
        ],
      ),
    );
  }

  // ── Stay management ──────────────────────────────────────────────────────

  Widget _stayManagement(StayBooking b) {
    final bool started = b.status == BookingStatus.inProgress ||
        b.status == BookingStatus.confirmed;

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Padding(
          padding: const EdgeInsets.only(left: 20, bottom: 8),
          child: Text('Your stay',
              style: GoogleFonts.inter(
                  fontSize: 16,
                  fontWeight: FontWeight.bold,
                  color: GoOutsColors.deepNavy)),
        ),
        _card(
          padding: EdgeInsets.zero,
          child: Column(
            children: [
              if (started)
                _tile(
                  Icons.map_outlined,
                  'Trip details',
                  'Check-in times, access and the host',
                  () => Navigator.of(context).pushNamed(
                    StayRoutes.trip,
                    arguments: <String, dynamic>{'bookingId': b.id},
                  ),
                ),
              if (started)
                _tile(
                  Icons.photo_camera_outlined,
                  'Arrival photographs',
                  'Your evidence if a damage claim is made',
                  () => Navigator.of(context).pushNamed(
                    StayRoutes.captureIntro,
                    arguments: <String, dynamic>{
                      'bookingId': b.id,
                      'captureKind': CaptureKind.guestCheckIn.wire,
                    },
                  ),
                ),
              _tile(
                Icons.folder_outlined,
                'Evidence pack',
                'Every photograph held for this stay',
                () => Navigator.of(context).pushNamed(
                  StayRoutes.evidencePack,
                  arguments: <String, dynamic>{'bookingId': b.id},
                ),
                last: true,
              ),
            ],
          ),
        ),
      ],
    );
  }

  Widget _tile(IconData icon, String title, String subtitle, VoidCallback onTap,
          {bool last = false}) =>
      Column(
        children: [
          ListTile(
            leading: Icon(icon, color: GoOutsColors.primaryBlue),
            title: Text(title,
                style: GoogleFonts.inter(
                    fontSize: 15,
                    fontWeight: FontWeight.w600,
                    color: GoOutsColors.deepNavy)),
            subtitle: Text(subtitle,
                style: GoogleFonts.inter(
                    fontSize: 13, color: GoOutsColors.bodyText)),
            trailing: const Icon(Icons.chevron_right,
                color: GoOutsColors.bodyText),
            onTap: onTap,
          ),
          if (!last)
            const Divider(height: 1, indent: 16, endIndent: 16,
                color: GoOutsColors.dividerGray),
        ],
      );

  // ── Price ────────────────────────────────────────────────────────────────
  //
  // From booking.pricing, which is the snapshot taken when the booking was
  // made — NOT a fresh quote. A guest looking at a stay they booked in July
  // must see July's price, whatever the config says today.

  Widget _paymentSummary(StayBooking b) {
    final p = b.pricing;
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Padding(
          padding: const EdgeInsets.only(left: 20, bottom: 8),
          child: Text('Price',
              style: GoogleFonts.inter(
                  fontSize: 16,
                  fontWeight: FontWeight.bold,
                  color: GoOutsColors.deepNavy)),
        ),
        _card(
          child: Column(
            children: [
              _row('${p.nightlyRate.compact} × ${p.nights} '
                  '${p.nights == 1 ? 'night' : 'nights'}',
                  p.accommodationTotal.formatted),
              if (!p.cleaningFee.isZero)
                _row('Cleaning fee', p.cleaningFee.formatted),
              if (!p.serviceFee.isZero)
                _row('Service fee', p.serviceFee.formatted),
              const Divider(height: 24, color: GoOutsColors.dividerGray),
              Row(
                mainAxisAlignment: MainAxisAlignment.spaceBetween,
                children: [
                  Text('Total',
                      style: GoogleFonts.inter(
                          fontSize: 15,
                          fontWeight: FontWeight.bold,
                          color: GoOutsColors.deepNavy)),
                  Text(p.total.formatted,
                      style: GoogleFonts.inter(
                          fontSize: 17,
                          fontWeight: FontWeight.w800,
                          color: GoOutsColors.deepNavy)),
                ],
              ),
              const SizedBox(height: 10),
              Row(
                children: [
                  Icon(
                    b.cashbackAwarded
                        ? Icons.check_circle
                        : Icons.savings_outlined,
                    size: 16,
                    color: GoOutsColors.tealSecondary,
                  ),
                  const SizedBox(width: 6),
                  Expanded(
                    child: Text(
                      // Cashback is credited at check-out, so before then this
                      // says what WILL happen rather than implying it already
                      // has. After, it confirms it.
                      b.cashbackAwarded
                          ? 'Cashback has been added to your wallet.'
                          : 'Cashback is added to your wallet after you check '
                              'out.',
                      style: GoogleFonts.inter(
                          fontSize: 12.5, color: GoOutsColors.bodyText),
                    ),
                  ),
                ],
              ),
            ],
          ),
        ),
        const SizedBox(height: 10),
        Padding(
          padding: const EdgeInsets.symmetric(horizontal: 20),
          child: Text(
            'Reference ${b.id}',
            style: GoogleFonts.inter(
                fontSize: 11.5,
                color: GoOutsColors.bodyText.withValues(alpha: 0.75)),
          ),
        ),
      ],
    );
  }

  Widget _row(String label, String value) => Padding(
        padding: const EdgeInsets.symmetric(vertical: 4),
        child: Row(
          mainAxisAlignment: MainAxisAlignment.spaceBetween,
          children: [
            Expanded(
              child: Text(label,
                  style: GoogleFonts.inter(
                      fontSize: 14, color: GoOutsColors.bodyText)),
            ),
            Text(value,
                style: GoogleFonts.inter(
                    fontSize: 14, color: GoOutsColors.deepNavy)),
          ],
        ),
      );
}
